#include <cstdint>

#if !defined(__powerpc__) && !defined(__ppc__)
#include <cfenv>
#endif

// @ 0x82436530 | size: 0x30
// CRT _ctrlfp (also identified by the FLIRT map), formerly the autogenerated
// fiAsciiTokenizer_6530_g / placeholder _fp_set_fpscr_bits. Exception-enable
// bits are inverted in the CRT representation; the return is the OLD word.
uint32_t _ctrlfp(uint32_t desired, uint32_t mask) {
#if defined(__powerpc__) || defined(__ppc__)
    double registerValue;
    __asm__ volatile("mffs %0" : "=f"(registerValue));
    uint64_t bits;
    __builtin_memcpy(&bits, &registerValue, sizeof(bits));
    uint32_t old = static_cast<uint32_t>(bits);
#else
    // Native hosts have a different FP environment layout. Retain guest-only
    // bits per thread and translate rounding through fenv. This does not emulate
    // Xenon exception traps or arithmetic updates to its detailed status bits.
    static thread_local uint32_t guestFpscr;
    const int rounding[] = {FE_TONEAREST, FE_TOWARDZERO, FE_UPWARD, FE_DOWNWARD};
    uint32_t old = guestFpscr;
    int currentRounding = std::fegetround();
    for (uint32_t i = 0; i < 4; ++i) {
        if (rounding[i] == currentRounding) old = (old & ~3u) | i;
    }
#endif
    uint32_t updated = ((desired ^ 0xF8u) & mask) | (old & ~mask);
#if defined(__powerpc__) || defined(__ppc__)
    bits = (bits & 0xffffffff00000000ULL) | updated;
    __builtin_memcpy(&registerValue, &bits, sizeof(bits));
    __asm__ volatile("mtfsf 255, %0" : : "f"(registerValue) : "memory");
#else
    guestFpscr = updated;
    std::fesetround(rounding[guestFpscr & 3]);
#endif
    return old ^ 0xF8u;
}
